"""Small dependency graph used by the PUPIS generative-coder proof."""


class TaskGraph:
    def __init__(self, dependencies):
        if not isinstance(dependencies, dict):
            raise TypeError("dependencies must be a mapping")

        self._deps = {}
        for task, deps in dependencies.items():
            if not isinstance(task, str) or not task:
                raise ValueError("task identifiers must be non-empty strings")
            if task in self._deps:
                raise ValueError(f"duplicate task identifier: {task}")
            normalized_deps = set()
            for dep in deps:
                if not isinstance(dep, str) or not dep:
                    raise ValueError("dependency identifiers must be non-empty strings")
                normalized_deps.add(dep)
            self._deps[task] = normalized_deps

        missing = set().union(*self._deps.values()) - set(self._deps) if self._deps else set()
        for task in missing:
            self._deps[task] = set()
        self._assert_acyclic()

    def _assert_acyclic(self):
        visiting = set()
        visited = set()

        def visit(task):
            if task in visiting:
                raise ValueError(f"dependency cycle detected at {task}")
            if task in visited:
                return
            visiting.add(task)
            for dep in self._deps[task]:
                visit(dep)
            visiting.remove(task)
            visited.add(task)

        for task in self._deps:
            visit(task)

    def ready_tasks(self, completed=()):
        done = set()
        for item in completed:
            if not isinstance(item, str) or not item:
                raise ValueError("completed task identifiers must be non-empty strings")
            done.add(item)

        ready = [
            task
            for task, deps in self._deps.items()
            if task not in done and deps.issubset(done)
        ]
        return sorted(ready)

import unittest
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "workspace"))
from task_graph import TaskGraph


class TaskGraphTests(unittest.TestCase):
    def test_ready_tasks_are_lexicographically_sorted(self):
        graph = TaskGraph({
            "compile": {"fetch"},
            "lint": set(),
            "fetch": set(),
            "package": {"compile", "lint"},
        })
        self.assertEqual(graph.ready_tasks(), ["fetch", "lint"])
        self.assertEqual(graph.ready_tasks({"fetch"}), ["compile", "lint"])
        self.assertEqual(graph.ready_tasks({"fetch", "lint", "compile"}), ["package"])

    def test_unknown_completed_names_do_not_change_semantics(self):
        graph = TaskGraph({"a": set(), "b": {"a"}})
        self.assertEqual(graph.ready_tasks({"ghost"}), ["a"])

    def test_cycle_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "cycle"):
            TaskGraph({"a": {"b"}, "b": {"a"}})

    def test_non_string_task_identifier_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "task identifiers"):
            TaskGraph({1: set(), "1": {"x"}})

    def test_non_string_dependency_identifier_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "dependency identifiers"):
            TaskGraph({"a": {1}})


if __name__ == "__main__":
    unittest.main()
